-- Frozen v6.13.9 schema, migration ledger, and default settings. See README.md.
CREATE TABLE `client_searchee` (`client_host` varchar(255), `info_hash` varchar(255), `name` varchar(255), `title` varchar(255), `files` json, `length` integer, `save_path` varchar(255), `category` varchar(255), `tags` json, `trackers` json, primary key (`client_host`, `info_hash`));
CREATE TABLE `data` (`path` varchar(255), `title` varchar(255), primary key (`path`));
CREATE TABLE `decision` (`id` integer not null primary key autoincrement, `searchee_id` integer, `guid` varchar(255), `info_hash` varchar(255), `decision` varchar(255), `first_seen` integer, `last_seen` integer, `fuzzy_size_factor` float default '0.02', foreign key(`searchee_id`) references `searchee`(`id`));
CREATE TABLE `ensemble` (`client_host` varchar(255), `path` varchar(255), `info_hash` varchar(255), `ensemble` varchar(255), `element` varchar(255), primary key (`client_host`, `path`));
CREATE TABLE `indexer` (`id` integer not null primary key autoincrement, `url` varchar(255), `apikey` varchar(255), `active` boolean, `status` varchar(255), `retry_after` integer, `search_cap` boolean null, `tv_search_cap` boolean null, `movie_search_cap` boolean null, `tv_id_caps` json, `movie_id_caps` json, `cat_caps` json, `limits_caps` json, `name` varchar(255), `music_search_cap` boolean null, `audio_search_cap` boolean null, `book_search_cap` boolean null, `trackers` json);
CREATE TABLE `job_log` (`id` integer not null primary key autoincrement, `name` varchar(255), `last_run` integer);
CREATE TABLE `knex_migrations` (`id` integer not null primary key autoincrement, `name` varchar(255), `batch` integer, `migration_time` datetime);
CREATE TABLE `knex_migrations_lock` (`index` integer not null primary key autoincrement, `is_locked` integer);
CREATE TABLE `rss` (`indexer_id` integer, `last_seen_guid` varchar(255), foreign key(`indexer_id`) references `indexer`(`id`), primary key (`indexer_id`));
CREATE TABLE `searchee` (`id` integer not null primary key autoincrement, `name` varchar(255), `first_searched` integer, `last_searched` integer);
CREATE TABLE `settings` (`id` integer, `apikey` varchar(255), primary key (`id`), check (id = 0));
CREATE TABLE `timestamp` (`searchee_id` integer, `indexer_id` integer, `first_searched` integer, `last_searched` integer, foreign key(`searchee_id`) references `searchee`(`id`), foreign key(`indexer_id`) references `indexer`(`id`), primary key (`searchee_id`, `indexer_id`));
CREATE TABLE `torrent` (`id` integer not null primary key autoincrement, `info_hash` varchar(255), `name` varchar(255), `file_path` varchar(255));
CREATE INDEX `client_searchee_info_hash_index` on `client_searchee` (`info_hash`);
CREATE UNIQUE INDEX `decision_searchee_id_guid_unique` on `decision` (`searchee_id`, `guid`);
CREATE INDEX `ensemble_info_hash_index` on `ensemble` (`info_hash`);
CREATE INDEX `ensemble_path_index` on `ensemble` (`path`);
CREATE INDEX `idx_decision_guid` on `decision` (`guid`);
CREATE INDEX `idx_decision_info_hash` on `decision` (`info_hash`);
CREATE INDEX `idx_decision_info_hash_guid` on `decision` (`info_hash`, `guid`);
CREATE UNIQUE INDEX `indexer_url_unique` on `indexer` (`url`);
CREATE UNIQUE INDEX `job_log_name_unique` on `job_log` (`name`);
CREATE UNIQUE INDEX `searchee_name_unique` on `searchee` (`name`);
CREATE UNIQUE INDEX `torrent_file_path_unique` on `torrent` (`file_path`);
